#!/bin/sh
# CI gate: every rule copy must contain byte-identical canonical body text.
#
# Copies are generated by gen-rule-copies.sh. If this check drifts, either a
# copy was hand-edited (forbidden: regenerate) or the canonical text changed
# without regenerating; both are fixed by running gen-rule-copies.sh.
set -eu

ROOT=$(cd "$(dirname "$0")/.." && pwd)
CANONICAL="$ROOT/plugins/memvault/rules/memvault.md"

body=$(sed -n '/memvault:canonical-begin/,/memvault:canonical-end/p' "$CANONICAL")
[ -n "$body" ] || { echo "no canonical block in $CANONICAL" >&2; exit 1; }

status=0
for copy in integrations/rules/cursor.mdc integrations/rules/clinerules.md \
    integrations/rules/kiro-steering.md integrations/rules/agents-snippet.md \
    .qoder/rules/memvault.md; do
    path="$ROOT/$copy"
    if [ ! -f "$path" ]; then
        echo "missing copy: $copy"
        status=1
        continue
    fi
    if grep -qF "$body" "$path"; then
        echo "ok - $copy in sync"
    else
        echo "out of sync: $copy (run scripts/gen-rule-copies.sh)"
        status=1
    fi
done

# Generated skill copies must stay byte-identical to the plugin source dir.
for tree in "$ROOT/skills" "$ROOT/.openclaw/skills"; do
    if diff -rq -x .DS_Store "$ROOT/plugins/memvault/skills" "$tree" >/dev/null 2>&1; then
        echo "ok - ${tree#"$ROOT/"} in sync"
    else
        echo "out of sync: ${tree#"$ROOT/"} (run scripts/gen-rule-copies.sh)"
        status=1
    fi
done

# Command variants are NOT copies — each host gets its own wording — so byte
# parity cannot apply. They are checked by content instead: a safety-critical
# instruction must survive in every variant, or a rewrite of one would silently
# drop it and CI would stay green.
#
# `proposes_supersede_of` is the one currently gated this way. A pending edit
# proposal is indistinguishable from a near-duplicate draft (same namespace,
# near-identical content, both unreviewed), so a reviewer who is not told to check
# the field will reject it as a duplicate — silently discarding a correction — or
# approve it without knowing a different memory is about to be superseded. See
# docs/DESIGN.md §9.3.1.
for copy in commands/memvault-review.toml \
    plugins/memvault/commands/memvault-review.md \
    integrations/codex/prompts/memvault-review.md \
    integrations/opencode/command/memvault-review.md; do
    path="$ROOT/$copy"
    if [ ! -f "$path" ]; then
        echo "missing command variant: $copy"
        status=1
        continue
    fi
    if grep -q 'proposes_supersede_of' "$path"; then
        echo "ok - $copy carries the proposal check"
    else
        echo "missing safety note: $copy must tell the reviewer to check proposes_supersede_of"
        status=1
    fi
done

exit "$status"
